import{_ as e,o as r,c as t,b3 as i}from"./chunks/framework.VnelH-cX.js";const p=JSON.parse('{"title":"界面设置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings/ui.md","filePath":"guide/settings/ui.md","lastUpdated":1786700458000}'),h={name:"guide/settings/ui.md"};function o(l,a,n,d,s,u){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="界面设置" tabindex="-1">界面设置 <a class="header-anchor" href="#界面设置" aria-label="Permalink to &quot;界面设置&quot;">​</a></h1><p>界面设置允许您自定义 Wing Shot 的外观颜色，包括主题、布局、动画效果等。</p><h2 id="常用" tabindex="-1">常用 <a class="header-anchor" href="#常用" aria-label="Permalink to &quot;常用&quot;">​</a></h2><p>常用标签页包含基础的界面配置选项。</p><h3 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to &quot;主题&quot;">​</a></h3><p>选择应用的主题样式：</p><ul><li><strong>跟随系统</strong>：自动跟随操作系统的明暗主题设置</li><li><strong>浅色</strong>：固定使用浅色主题</li><li><strong>暗黑</strong>：固定使用暗黑主题</li></ul><h3 id="语言" tabindex="-1">语言 <a class="header-anchor" href="#语言" aria-label="Permalink to &quot;语言&quot;">​</a></h3><p>选择应用界面显示的语言。支持简体中文、English 等多种语言。</p><h2 id="截图" tabindex="-1">截图 <a class="header-anchor" href="#截图" aria-label="Permalink to &quot;截图&quot;">​</a></h2><p>截图标签页包含与截图功能相关的界面设置。</p><h3 id="界面缩放比例" tabindex="-1">界面缩放比例 <a class="header-anchor" href="#界面缩放比例" aria-label="Permalink to &quot;界面缩放比例&quot;">​</a></h3><p>调整截图编辑界面的整体缩放比例。适合不同分辨率的屏幕显示。</p><h3 id="工具栏缩放比例" tabindex="-1">工具栏缩放比例 <a class="header-anchor" href="#工具栏缩放比例" aria-label="Permalink to &quot;工具栏缩放比例&quot;">​</a></h3><p>调整截图编辑工具栏的缩放比例。可以独立于界面缩放进行调整。</p><h3 id="选区控件样式" tabindex="-1">选区控件样式 <a class="header-anchor" href="#选区控件样式" aria-label="Permalink to &quot;选区控件样式&quot;">​</a></h3><p>选择截图选区控制点的样式。</p><h3 id="禁用动画" tabindex="-1">禁用动画 <a class="header-anchor" href="#禁用动画" aria-label="Permalink to &quot;禁用动画&quot;">​</a></h3><p>启用后，将禁用自动框选时截图选区的过渡效果，降低软件的性能需求。</p><h3 id="蒙色拾取器模式" tabindex="-1">蒙色拾取器模式 <a class="header-anchor" href="#蒙色拾取器模式" aria-label="Permalink to &quot;蒙色拾取器模式&quot;">​</a></h3><p>控制截图时蒙色拾取器（颜色选择器）的显示行为。</p><h3 id="选区遮罩颜色" tabindex="-1">选区遮罩颜色 <a class="header-anchor" href="#选区遮罩颜色" aria-label="Permalink to &quot;选区遮罩颜色&quot;">​</a></h3><p>设置截图时选区外部遮罩层的颜色和不透明度。</p><h3 id="超出选区范围的元素透明度" tabindex="-1">超出选区范围的元素透明度 <a class="header-anchor" href="#超出选区范围的元素透明度" aria-label="Permalink to &quot;超出选区范围的元素透明度&quot;">​</a></h3><p>调整选区外部区域绘制内容的透明度。</p><h3 id="快捷键提示透明度" tabindex="-1">快捷键提示透明度 <a class="header-anchor" href="#快捷键提示透明度" aria-label="Permalink to &quot;快捷键提示透明度&quot;">​</a></h3><p>调整截图时快捷键提示文字的透明度。</p><h3 id="全屏辅助线颜色" tabindex="-1">全屏辅助线颜色 <a class="header-anchor" href="#全屏辅助线颜色" aria-label="Permalink to &quot;全屏辅助线颜色&quot;">​</a></h3><p>设置全屏截图时辅助线的颜色和不透明度。辅助线可以帮助对齐元素。</p><h3 id="显示器中心辅助线颜色" tabindex="-1">显示器中心辅助线颜色 <a class="header-anchor" href="#显示器中心辅助线颜色" aria-label="Permalink to &quot;显示器中心辅助线颜色&quot;">​</a></h3><p>设置显示器中心辅助线的颜色和不透明度。</p><h3 id="蒙色拾取器中心辅助线颜色" tabindex="-1">蒙色拾取器中心辅助线颜色 <a class="header-anchor" href="#蒙色拾取器中心辅助线颜色" aria-label="Permalink to &quot;蒙色拾取器中心辅助线颜色&quot;">​</a></h3><p>设置蒙色拾取器中心十字辅助线的颜色和不透明度。</p><h3 id="隐藏工具栏工具" tabindex="-1">隐藏工具栏工具 <a class="header-anchor" href="#隐藏工具栏工具" aria-label="Permalink to &quot;隐藏工具栏工具&quot;">​</a></h3><p>选择需要在截图编辑工具栏中隐藏的工具。可以隐藏不常用的工具，使工具栏更简洁。</p><h2 id="固定到屏幕" tabindex="-1">固定到屏幕 <a class="header-anchor" href="#固定到屏幕" aria-label="Permalink to &quot;固定到屏幕&quot;">​</a></h2><p>固定到屏幕功能允许您将截图固定在桌面上，作为参考或对比使用。</p><h3 id="边框颜色" tabindex="-1">边框颜色 <a class="header-anchor" href="#边框颜色" aria-label="Permalink to &quot;边框颜色&quot;">​</a></h3><p>设置固定到屏幕的截图窗口边框颜色。</p><h2 id="托盘" tabindex="-1">托盘 <a class="header-anchor" href="#托盘" aria-label="Permalink to &quot;托盘&quot;">​</a></h2><p>托盘标签页包含系统托盘图标的相关设置。</p><h3 id="启用托盘" tabindex="-1">启用托盘 <a class="header-anchor" href="#启用托盘" aria-label="Permalink to &quot;启用托盘&quot;">​</a></h3><p>启用后，应用将在系统托盘显示图标，方便快速访问应用功能。</p><h3 id="默认图标" tabindex="-1">默认图标 <a class="header-anchor" href="#默认图标" aria-label="Permalink to &quot;默认图标&quot;">​</a></h3><p>选择系统托盘显示的图标样式。</p><h3 id="自定义图标路径" tabindex="-1">自定义图标路径 <a class="header-anchor" href="#自定义图标路径" aria-label="Permalink to &quot;自定义图标路径&quot;">​</a></h3><p>如果默认图标不满足需求，可以指定自定义图标文件的路径。支持 PNG 格式。</p>',47)])])}const b=e(h,[["render",o]]);export{p as __pageData,b as default};
